# 1. Define the task with structured output doc_analyzer <- signature(   inputs = list(     input("document", description = "Document text to analyze")   ),   output_type = type_object(     summary = type_string(       description = "Concise summary of main points"     ),     topics = type_array(       type_string(),       description = "Key topics discussed (max 5)"     ),     sentiment = type_enum(       values = c("positive", "negative", "neutral", "mixed"),       description = "Overall document sentiment"     ),     key_facts = type_array(       type_string(),       description = "Important facts or claims"     ),     recommendation = type_enum(       values = c("approve", "review", "reject"),       description = "Recommended action"     )   ),   instructions = "Analyze documents for key information and provide recommendations." ) |>   module(type = "predict")  # 2. Create comprehensive training data doc_trainset <- dsp_trainset(   document = c(     "Our Q3 revenue increased by 25% YoY, driven by strong product sales.      Customer satisfaction scores reached an all-time high of 92%.      We're expanding into three new markets next quarter.",      "Project delays have caused budget overruns of 40%. Team morale is low.      Three key engineers resigned last month. Urgent intervention needed.",      "The new policy proposal includes both benefits and drawbacks.      Cost savings of $2M are projected, but implementation challenges exist.      Stakeholder feedback has been mixed, requiring further consultation.",      "Annual environmental impact assessment shows 30% reduction in emissions.      Water usage decreased by 15%. All regulatory requirements met.      Received sustainability award from industry association."   ),   summary = c(     "Q3 showed strong 25% revenue growth with record customer satisfaction at 92%, prompting expansion into three new markets.",     "Project facing severe issues with 40% budget overrun, low team morale, and loss of three key engineers.",     "Policy proposal offers $2M savings but faces implementation challenges and mixed stakeholder reception.",     "Environmental performance improved with 30% emission reduction and 15% less water usage, earning industry recognition."   ),   topics = list(     c("revenue growth", "customer satisfaction", "market expansion"),     c("project delays", "budget overrun", "staff turnover", "morale"),     c(       "policy proposal",       "cost savings",       "implementation",       "stakeholder feedback"     ),     c(       "environmental impact",       "emissions reduction",       "sustainability",       "compliance"     )   ),   sentiment = c("positive", "negative", "mixed", "positive"),   key_facts = list(     c("25% YoY revenue increase", "92% customer satisfaction", "3 new markets"),     c("40% budget overrun", "3 engineers resigned", "low morale"),     c("$2M projected savings", "mixed stakeholder feedback"),     c("30% emission reduction", "15% water usage decrease", "industry award")   ),   recommendation = c("approve", "reject", "review", "approve") )  # 3. Define evaluation metrics # Create a weighted composite metric composite_metric <- function(pred, exp) {   scores <- c(     summary = metric_f1(field = "summary")(pred, exp),     sentiment = metric_exact_match(field = "sentiment")(pred, exp),     recommendation = metric_exact_match(field = "recommendation")(pred, exp)   )    # Weighted average   weights <- c(summary = 0.3, sentiment = 0.3, recommendation = 0.4)   sum(scores * weights) }  wrapped_metric <- metric_custom(composite_metric, name = "composite_score")  # 4. Test multiple optimization strategies # Strategy A: Few-shot with different k values results_by_k <- list()  for (k in c(1L, 2L, 3L, 4L)) {   teleprompter <- LabeledFewShot(k = k, seed = 42L)    optimized <- compile_module(     program = doc_analyzer,     teleprompter = teleprompter,     trainset = doc_trainset   )    # Evaluate on validation set   eval_result <- evaluate_dsp(     module = optimized,     data = doc_trainset, # In practice, use separate validation set     metric = wrapped_metric,     .llm = llm,     verbose = FALSE   )    results_by_k[[paste0("k_", k)]] <- eval_result$mean_score } #> Warning: Multiple potential output columns found #> ℹ Using: summary #> ℹ Other columns: topics, sentiment, key_facts, and recommendation #> Multiple potential output columns found #> ℹ Using: summary #> ℹ Other columns: topics, sentiment, key_facts, and recommendation #> Multiple potential output columns found #> ℹ Using: summary #> ℹ Other columns: topics, sentiment, key_facts, and recommendation #> Multiple potential output columns found #> ℹ Using: summary #> ℹ Other columns: topics, sentiment, key_facts, and recommendation  print(results_by_k) # See which k works best #> $k_1 #> [1] 0.7622253 #>  #> $k_2 #> [1] 0.7840854 #>  #> $k_3 #> [1] 0.7640367 #>  #> $k_4 #> [1] 0.8172435  # Strategy B: Grid search over different instruction styles instruction_variants <- data.frame(   id = c("executive", "technical"),   instructions_suffix = c(     ". Focus on business impact and executive decision-making.",     ". Emphasize technical accuracy and detailed analysis."   ),   template = c(     "Executive Analysis Required:
{document}

